import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int N = Integer.parseInt(br.readLine().trim());
        int[] A = new int[N + 1];
        StringTokenizer st = new StringTokenizer(br.readLine());
        for (int i = 1; i <= N; i++) {
            if (!st.hasMoreTokens()) {
                st = new StringTokenizer(br.readLine());
            }
            A[i] = Integer.parseInt(st.nextToken());
        }

        long[] arr = new long[N];
        for (int i = 1; i <= N; i++) {
            arr[i - 1] = ((long) A[i] << 20) | i;
        }
        Arrays.sort(arr);

        boolean[] active = new boolean[N + 2];
        int intervals = 0;
        int maxIntervals = 0;

        int i = N - 1;
        while (i >= 0) {
            long val = arr[i];
            int height = (int) (val >> 20);
            int j = i;
            while (j >= 0 && (arr[j] >> 20) == height) {
                int idx = (int) (arr[j] & ((1 << 20) - 1));
                active[idx] = true;
                boolean left = active[idx - 1];
                boolean right = active[idx + 1];
                if (left && right) {
                    intervals--;
                } else if (!left && !right) {
                    intervals++;
                }
                j--;
            }
            if (intervals > maxIntervals) {
                maxIntervals = intervals;
            }
            i = j;
        }

        System.out.println(maxIntervals + 1);
    }
}
